const searchBarInjections = new Map();

export const registerSearchBarControl = async ({ moduleName, controlId, tree, position = 'end' }) => {
    searchBarInjections.set(`${moduleName}-${controlId}`, { tree, position, moduleName });
    await refreshSearchBarControls();
};

export const unregisterSearchBarControl = async (moduleName, controlId) => {
    searchBarInjections.delete(`${moduleName}-${controlId}`);
    await refreshSearchBarControls();
};

const refreshSearchBarControls = async () => {
    const buttonGroup = document.querySelector('#cognition-search-bar [style*="display: flex"]');
    if (!buttonGroup) return;

    // Clear existing injected controls
    buttonGroup.innerHTML = '';

    // Re-render all registered controls
    for (const [key, { tree }] of searchBarInjections) {
        await runtime.call('tree-to-dom.transform', tree, buttonGroup);
    }
};
```

