    // Register UI controls
    await runtime.call('ui.registerSearchBarControl', {
        moduleName: 'web-speech-tts',
        controlId: 'speaker',
        tree: {
            "speech-button": { 
                tag: "button", 
                id: "speech-button", 
                text: "🔊", 
                class: "cognition-button-secondary", 
                style: "min-width: 40px; height: 40px; border-radius: 50%; font-size: 18px;", 
                events: { click: "web-speech-tts.speakPrompt" } 
            }
        }
    });
};

export const speakPrompt = async () => {
    const searchInput = document.querySelector('#cognition-search-input');
    const text = searchInput?.value?.trim();
    if (!text) return;

    const button = document.querySelector('#speech-button');
    if (button) button.textContent = '⏳';

    try {
        const settings = await getSettings();
        const result = await speak(text, settings);
        if (!result.success) runtime.logError('[TTS] Failed:', result.error);
    } catch (error) {
        runtime.logError('[TTS] Error:', error);
    } finally {
        if (button) button.textContent = '🔊';
    }
};
```

